import re, os

# For each .rs file, find .unwrap() calls NOT inside #[cfg(test)] blocks
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()

        # Find the start of #[cfg(test)] mod tests block
        test_start = None
        for m in re.finditer(r'#\[cfg\(test\)\]', content):
            test_start = m.start()
            break

        lines = content.split('\n')
        in_test = False
        for i, line in enumerate(lines, 1):
            if test_start is not None:
                pos = sum(len(l)+1 for l in lines[:i-1])
                if pos >= test_start:
                    in_test = True

            if not in_test and '.unwrap()' in line:
                print(f'{path}:{i}: {line.strip()}')
"

