//! Interactive prompts.

use console::{measure_text_width, style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Check whether a key is Ctrl+D (EOF signal in terminals).
fn is_ctrl_d(key: &Key) -> bool {
    matches!(key, Key::Char('\x04'))
}

/// Check whether an IO error represents EOF (end-of-file).
fn is_eof_error(err: &std::io::Error) -> bool {
    err.kind() == std::io::ErrorKind::UnexpectedEof
}

/// Convert EOF IO errors to `PromptInterrupted`, pass others through.
fn map_eof_to_interrupted(err: BivvyError) -> BivvyError {
    if let BivvyError::Io(ref io_err) = err {
        if is_eof_error(io_err) {
            return BivvyError::PromptInterrupted;
        }
    }
    err
}

/// Convert dialoguer errors to BivvyError, mapping EOF to PromptInterrupted.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: std::io::Error = e.into();
    if is_eof_error(&io_err) {
        BivvyError::PromptInterrupted
    } else {
        BivvyError::Io(io_err)
    }
}

