        let err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        assert!(is_eof_error(&err));
    }

    #[test]
    fn is_eof_error_rejects_other_errors() {
        let err = std::io::Error::new(std::io::ErrorKind::NotFound, "not found");
        assert!(!is_eof_error(&err));
    }

    #[test]
    fn is_ctrl_d_key_detects_ctrl_d() {
        assert!(is_ctrl_d(&Key::Char('\x04')));
    }

    #[test]
    fn is_ctrl_d_key_rejects_other_keys() {
        assert!(!is_ctrl_d(&Key::Char('a')));
        assert!(!is_ctrl_d(&Key::Enter));
        assert!(!is_ctrl_d(&Key::Escape));
    }

    #[test]
    fn map_eof_to_interrupted_converts_eof() {
        let io_err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let bivvy_err = BivvyError::Io(io_err);
        let result = map_eof_to_interrupted(bivvy_err);
        assert!(matches!(result, BivvyError::PromptInterrupted));
    }

    #[test]
    fn map_eof_to_interrupted_preserves_other_errors() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "not found");
        let bivvy_err = BivvyError::Io(io_err);
        let result = map_eof_to_interrupted(bivvy_err);
        assert!(matches!(result, BivvyError::Io(_)));
    }
}

